//! Primitives: library introspection ((scm module) %load-module,
//! %module-exports, %module-ref) over the table of every library's exports
//! (library_exports.zig, generated by tools/gen-library-exports.scm), so
//! that (scm source) can tell what an import provides (scm lint, scm fmt)
//! also for libraries that are not linked into the program.
//!
//! %module-ref gives a stand-in of the binding's kind: a macro object for
//! syntax, a procedure that raises an error when called for procedures,
//! the unspecified value for other values (values themselves need eval).
const std = @import("std");
const rt = @import("rt.zig");
const data = @import("data.zig");
const printer = @import("printer.zig");
const sys = @import("prims_sys.zig");
const lib = @import("library_exports.zig");
const P = @import("prims.zig");
const Word = rt.Word;
const Thread = rt.Thread;
const Err = P.Err;
const WN = P.WN;
const arg = P.arg;
const raise = P.raise;

const pa = std.heap.c_allocator;

/// The library named by w: a list like (scheme base) or a string like
/// "scheme base"
fn findLibrary(w: Word) ?*const lib.Library {
    var b: std.ArrayList(u8) = .empty;
    defer b.deinit(pa);
    if (data.isString(w)) {
        b.append(pa, '(') catch rt.oom();
        b.appendSlice(pa, data.toUtf8(w)) catch rt.oom();
        b.append(pa, ')') catch rt.oom();
    } else printer.print(&b, w, true);
    for (&lib.libraries) |*l| if (std.mem.eql(u8, l.name, b.items)) return l;
    return null;
}

fn libraryArg(t: *Thread, who: []const u8) Err!*const lib.Library {
    return findLibrary(arg(t, 0)) orelse
        raise(t, std.fmt.allocPrint(pa, "{s}: module ~a not found", .{who}) catch rt.oom(), &.{arg(t, 0)});
}

fn loadModule(t: *Thread) Err!Word {
    _ = try libraryArg(t, "%load-module");
    return rt.TRUE;
}
pub const @"%%load-module" = WN("%load-module", loadModule, 1, 2);

/// the export names, sorted (as the JVM implementation)
fn moduleExports(t: *Thread) Err!Word {
    const l = try libraryArg(t, "%module-exports");
    var names: std.ArrayList([]const u8) = .empty;
    defer names.deinit(pa);
    for (l.exports) |e| names.append(pa, e.name) catch rt.oom();
    std.mem.sort([]const u8, names.items, {}, struct {
        fn lt(_: void, a: []const u8, b: []const u8) bool {
            return std.mem.order(u8, a, b) == .lt;
        }
    }.lt);
    t.reserve(3 * names.items.len);
    var r = rt.NIL;
    var i = names.items.len;
    while (i > 0) {
        i -= 1;
        r = t.cons(data.intern(names.items[i]), r);
    }
    return r;
}
pub const @"%%module-exports" = WN("%module-exports", moduleExports, 1, 1);

fn standinCode(t: *Thread) callconv(.c) void {
    return @call(.always_tail, rt.fail(t, "this procedure is only described (no value of it in a native program)", &.{}), .{t});
}

/// one stand-in per binding identity, so that eq? tells re-exports from
/// distinct bindings (as the JVM implementation's values do)
var standins: [lib.id_count]?Word = @splat(null);
var markers: [lib.id_count]u8 = @splat(0);

fn standin(e: lib.Export) Word {
    if (standins[e.id]) |w| return w;
    const w = switch (e.kind) {
        .syntax => blk: {
            const q = rt.staticAlloc(3, false);
            q[0] = rt.hdr(rt.T_NATIVE, 2);
            q[1] = @intFromEnum(sys.NativeKind.macro_standin);
            q[2] = @intFromPtr(&markers[e.id]);
            break :blk rt.tagPtr(q);
        },
        .procedure => rt.primitive(&standinCode, "described-procedure"),
        .value, .unknown => blk: {
            // a distinct object for each value: a static one-element vector
            const q = rt.staticAlloc(2, false);
            q[0] = rt.hdr(rt.T_VECTOR, 1);
            q[1] = rt.UNSPEC;
            break :blk rt.tagPtr(q);
        },
    };
    if (e.id != 0) standins[e.id] = w;
    return w;
}

fn moduleRef(t: *Thread) Err!Word {
    const l = try libraryArg(t, "%module-ref");
    const s = arg(t, 1);
    if (!data.isSymbol(s)) return P.argTypeError(t);
    const name = data.symbolName(s);
    for (l.exports) |e| if (std.mem.eql(u8, e.name, name)) return standin(e);
    return raise(t, std.fmt.allocPrint(pa, "{s} is not bound", .{name}) catch rt.oom(), &.{});
}
pub const @"%%module-ref" = WN("%module-ref", moduleRef, 2, 2);

// --- procedure-doc ---------------------------------------------------------------

/// docstrings of lambdas by their code (set by the modules' initialization)
var docs: std.AutoHashMapUnmanaged(usize, []const u8) = .empty;

pub fn setDoc(code: rt.Code, doc: []const u8) void {
    docs.put(pa, @intFromPtr(code), doc) catch rt.oom();
}

/// The text of a primitive (primitive_docs.zig is sorted by name)
fn primitiveDoc(name: []const u8) ?[]const u8 {
    const table = @import("primitive_docs.zig").docs;
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        switch (std.mem.order(u8, table[mid].name, name)) {
            .eq => return table[mid].doc,
            .lt => lo = mid + 1,
            .gt => hi = mid,
        }
    }
    return null;
}

/// The docstring of a procedure (a primitive's text as the JVM
/// implementation's), or #f
fn procedureDoc(t: *Thread) Err!Word {
    const p = arg(t, 0);
    if (!(rt.isPtr(p) and rt.objType(p) == rt.T_CLOSURE)) return rt.FALSE;
    const doc = if (rt.isPrimitive(p))
        primitiveDoc(data.symbolName(rt.ptr(p)[2])) orelse return rt.FALSE
    else
        docs.get(rt.ptr(p)[1]) orelse return rt.FALSE;
    t.reserve(data.stringWords(doc.len, true));
    return data.heapStringUtf8(t, doc);
}
pub const @"%procedure-doc" = WN("procedure-doc", procedureDoc, 1, 1);
